layer.css:
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap");
[data-ryt="footer"] { color: var(--ryt-bg); background-color: rgb(2, 132, 199); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: #1099d8; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(14, 165, 233); text-decoration-thickness: auto; text-underline-offset: auto; transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1); position: relative }
[data-ryt="button"] { color: var(--ryt-bg); background-color: rgb(14, 165, 233); border-top: 2px solid rgba(0, 0, 0, 0); border-right: 2px solid rgba(0, 0, 0, 0); border-bottom: 2px solid rgba(0, 0, 0, 0); border-left: 2px solid rgba(0, 0, 0, 0); border-radius: 8px; box-shadow: rgba(14, 165, 233, 0.1) 0px 4px 6px -1px; font-family: var(--ryt-font-body); font-weight: 600; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 14px; padding-right: 32px; padding-bottom: 14px; padding-left: 32px; transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1) }
[data-ryt="button"]:hover { background-color: #0284c7; transform: translateY(-2px); box-shadow: 0 10px 15px -3px rgba(14, 165, 233, 0.1) }
[data-ryt="nav"] a::after { content: ""; display: block; position: absolute; height: 2px; color: var(--ryt-accent); background-color: rgb(14, 165, 233); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: width 0.3s; -webkit-text-fill-color: var(--ryt-accent); bottom: -5px; left: 0px }
[data-ryt="brand"]:hover { color: #0284c7 }
